<?php

namespace Tests\Feature;

use App\Models\User;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

class LegacyImporterTest extends TestCase
{
    use RefreshDatabase;

    // Generated by bcryptjs 3.x and bcryptjs 2.4.3 at cost 4, respectively.
    private const OWNER_BCRYPTJS_2B = '$2b$04$QcuJJOgL2hCi9QYJOnOPn.tL88FTewCcbcOamGdA127ByfgfBq9LC';
    private const FRIEND_BCRYPTJS_2A = '$2a$04$M4nTk1lXpn0l1C636bVn.e34t11jKiqhoiBeUa651eNMiJQnmatdq';
    private const SFTP_BCRYPTJS_2B = '$2b$04$Mh.eumZwm9lEfyWjhre9zujD0NWYuXvZ0UlRQ/2FUztVq5wb5ec9G';

    private string $temporaryRoot;
    private string $source;
    private string $backupDirectory;

    protected function setUp(): void
    {
        parent::setUp();
        if (DB::connection()->getDriverName() !== 'pgsql') {
            $this->markTestSkipped('The JSON importer intentionally requires PostgreSQL; run this test with DB_CONNECTION=pgsql.');
        }
        $this->temporaryRoot = storage_path('framework/testing/legacy-import-'.bin2hex(random_bytes(5)));
        $this->source = $this->temporaryRoot.'/.data';
        $this->backupDirectory = $this->temporaryRoot.'/backup';
        mkdir($this->source, 0700, true);
        $this->makeFixture();
    }

    protected function tearDown(): void
    {
        if (isset($this->temporaryRoot) && is_dir($this->temporaryRoot)) {
            $iterator = new \RecursiveIteratorIterator(
                new \RecursiveDirectoryIterator($this->temporaryRoot, \FilesystemIterator::SKIP_DOTS),
                \RecursiveIteratorIterator::CHILD_FIRST
            );
            foreach ($iterator as $item) $item->isDir() ? rmdir($item->getPathname()) : unlink($item->getPathname());
            rmdir($this->temporaryRoot);
        }
        parent::tearDown();
    }

    public function test_dry_run_is_read_only_and_full_import_is_atomic_lossless_and_idempotent(): void
    {
        $args = ['path' => $this->source, '--backup-dir' => $this->backupDirectory];
        $this->assertSame(0, Artisan::call('snck:import-json', $args + ['--dry-run' => true]), Artisan::output());
        $this->assertDatabaseCount('users', 0);
        $this->assertDatabaseCount('nodes', 0);
        $this->assertDatabaseCount('legacy_json_records', 0);

        $this->assertSame(0, Artisan::call('snck:import-json', $args), Artisan::output());
        $this->assertDatabaseCount('users', 2);
        $this->assertDatabaseCount('nodes', 1);
        $this->assertDatabaseCount('servers', 1);
        $this->assertDatabaseCount('allocations', 2);
        $this->assertDatabaseCount('server_subusers', 1);
        $this->assertDatabaseCount('legacy_json_records', 8);
        $this->assertDatabaseCount('sftp_users', 1);
        $this->assertCount(1, glob($this->backupDirectory.'/*.zip') ?: []);

        $this->assertDatabaseHas('setup_state', ['owner_user_id' => 'owner-1']);
        $ownerHash = (string) DB::table('users')->where('id', 'owner-1')->value('password');
        $friendHash = (string) DB::table('users')->where('id', 'friend-1')->value('password');
        $sftpHash = (string) DB::table('sftp_users')->where('id', 'sftp-1')->value('password_hash');
        $this->assertStringStartsWith('$2y$', $ownerHash);
        $this->assertStringStartsWith('$2y$', $friendHash);
        $this->assertStringStartsWith('$2y$', $sftpHash);
        $this->assertTrue(Hash::check('owner-bcryptjs-password', $ownerHash));
        $this->assertTrue(Hash::check('friend-bcryptjs-password', $friendHash));
        $this->assertTrue(Hash::check('sftp-bcryptjs-password', $sftpHash));

        $this->post('/login', ['identity' => 'owner', 'password' => 'owner-bcryptjs-password'])
            ->assertRedirect('/dashboard');
        $this->assertAuthenticatedAs(User::query()->findOrFail('owner-1'));
        $this->post('/logout')->assertRedirect('/login');
        $this->post('/login', ['identity' => 'friend', 'password' => 'friend-bcryptjs-password'])
            ->assertRedirect('/dashboard');
        $this->assertAuthenticatedAs(User::query()->findOrFail('friend-1'));

        $node = DB::table('nodes')->where('id', 'node-1')->first();
        $this->assertSame('offline', $node->status);
        $this->assertFalse((bool) $node->docker_available);
        $this->assertSame('daemon-test-token', Crypt::decryptString($node->credential_encrypted));
        $this->assertSame(2048, (int) DB::table('servers')->where('id', 'server-1')->value('memory_limit_mb'));
        $this->assertSame(10 * 1024, (int) DB::table('nodes')->where('id', 'node-1')->value('disk_limit_mb'));

        $permissions = DB::table('server_subusers')->where('server_id', 'server-1')->where('user_id', 'friend-1')->value('permissions');
        $this->assertEquals(['*', 'files'], json_decode($permissions, true));
        $storedState = DB::table('discord_reward_state')->where('id', 'default')->value('payload');
        $this->assertSame(['botToken' => 'preserve-this-secret'], json_decode(Crypt::decryptString(json_decode($storedState, true)), true));

        $this->assertSame(1, Artisan::call('snck:import-json', ['path' => $this->source, '--backup-dir' => $this->backupDirectory]));
        $this->assertSame(0, Artisan::call('snck:import-json', $args + ['--force' => true]), Artisan::output());
        $this->assertDatabaseCount('users', 2);
        $this->assertDatabaseCount('servers', 1);
        $this->assertDatabaseCount('allocations', 2);
    }

    public function test_insecure_remote_node_configuration_fails_dry_run_before_any_database_write(): void
    {
        $nodes = json_decode(file_get_contents($this->source.'/nodes.json'), true);
        $nodes[0]['tlsVerify'] = false;
        file_put_contents($this->source.'/nodes.json', json_encode($nodes, JSON_THROW_ON_ERROR));

        $this->assertSame(1, Artisan::call('snck:import-json', [
            'path' => $this->source,
            '--dry-run' => true,
            '--backup-dir' => $this->backupDirectory,
        ]));
        $this->assertStringContainsString('certificate verification cannot be disabled', Artisan::output());
        $this->assertDatabaseCount('nodes', 0);
        $this->assertDirectoryDoesNotExist($this->backupDirectory);
    }

    private function makeFixture(): void
    {
        $files = [
            'users.json' => [
                ['id' => 'owner-1', 'name' => 'Owner', 'username' => 'owner', 'email' => 'owner@example.test', 'role' => 'owner', 'passwordHash' => self::OWNER_BCRYPTJS_2B],
                ['id' => 'friend-1', 'name' => 'Friend', 'username' => 'friend', 'email' => 'friend@example.test', 'role' => 'user', 'passwordHash' => self::FRIEND_BCRYPTJS_2A],
            ],
            'nodes.json' => [[
                'id' => 'node-1', 'name' => 'Test node', 'hostname' => 'node.example.test', 'fqdn' => 'node.example.test',
                'apiPort' => 6768, 'sftpPort' => 2022, 'tls' => true, 'tlsVerify' => true,
                'memory' => 8192, 'disk' => 10, 'cpu' => 400, 'credential' => 'daemon-test-token',
                'createdAt' => '2026-01-01T00:00:00Z',
            ]],
            'servers.json' => [[
                'id' => 'server-1', 'owner' => 'owner-1', 'nodeId' => 'node-1', 'name' => 'Survival',
                'ram' => 2, 'disk' => 20, 'cpu' => 200, 'port' => 25565, 'status' => 'offline',
                'subUsers' => [['userId' => 'friend-1', 'permissions' => ['*', 'files']]],
            ]],
            'allocations.json' => [[
                'id' => 'allocation-1', 'nodeId' => 'node-1', 'ip' => '0.0.0.0', 'ipVersion' => 'IPv4',
                'portStart' => 25565, 'portEnd' => 25566, 'assignedServerId' => null,
            ]],
            'settings.json' => ['enableRegistration' => true],
            'discord_rewards.json' => ['botToken' => 'preserve-this-secret'],
            'sftp_users.json' => [[
                'id' => 'sftp-1', 'serverId' => 'server-1', 'username' => 'sftp-survival',
                'passwordHash' => self::SFTP_BCRYPTJS_2B,
            ]],
        ];
        foreach ($files as $name => $value) file_put_contents($this->source.'/'.$name, json_encode($value, JSON_PRETTY_PRINT | JSON_THROW_ON_ERROR));
    }
}
